{
  "implementation": "def solve(case):
    attempts = case['attempts']
    max_attempts = case['max_attempts']
    num = len(attempts)
    if num == 0:
        return {"decision": "retry", "memory_append": None, "next_attempt": 0}
    last = attempts[-1]
    if last['success']:
        return {"decision": "accept", "memory_append": None, "next_attempt": num}
    if num >= max_attempts:
        return {"decision": "give_up", "memory_append": None, "next_attempt": num}
    return {
        "decision": "retry",
        "memory_append": {"reflection": last['reflection'], "signature": last['failure_signature']},
        "next_attempt": num + 1
    }"
}
